export const title = "How to Build a Video-Call Background in a Room With No Blank Wall";
export const metaTitle = "How to Build a Video-Call Background in a Room";
export const metaDescription = "Create a video-call background without a blank wall using camera-frame checks, supported screens, and a quick reset routine.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-17";
export const readTime = "11 min";
